Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Module Ly := S1Layout.
Abbreviation SEGS := Plain.M.loaded_segments.

Definition PC_RET_FW1 : Z := 0xd6ad8.

Section Pass2.
  Context {fx : FPState}.
Context {RRND : RunRandom}.
  Variables (R : bvmap 5 word) (M : mem) (sp ret v conv : Z).

  Hypothesis Hra : getr R 1%bv = Z_to_bv 64 ret.
  Hypothesis Hret : ret_ok (Z_to_bv 64 ret).
  Hypothesis Hretr : 0 <= ret < 2 ^ 64.
  Hypothesis Hsp : getr R 2%bv = Z_to_bv 64 sp.
  Hypothesis Ha0 : getr R 10%bv = Z_to_bv 64 (sp + 368).
  Hypothesis Ha1 : getr R 11%bv = Z_to_bv 64 (sp + 848).
  Hypothesis Ha2 : getr R 12%bv = Z_to_bv 64 sp.
  Hypothesis Ha3 : getr R 13%bv = Z_to_bv 64 (sp + 96).
  Hypothesis Ha4 : getr R 14%bv = Z_to_bv 64 (sp + 264).
  Hypothesis Hsplo : 2 ^ 32 <= sp - 608.
  Hypothesis Hsphi : sp + 852 < 2 ^ 47.
  Hypothesis Hal : sp mod 16 = 0.
  Hypothesis HD : mdef M (sp - 608) 1460.
  Hypothesis Fap : fld SEGS M sp 8 (sp + 720).
  Hypothesis Fv : fld SEGS M (sp + 720) 8 v.
  Hypothesis Hv : 0 <= v < 2 ^ 64.
  Hypothesis F0 : fld SEGS M (sp + 848) 1 37.
  Hypothesis F1 : fld SEGS M (sp + 849) 1 108.
  Hypothesis F2 : fld SEGS M (sp + 850) 1 conv.
  Hypothesis F3 : fld SEGS M (sp + 851) 1 0.
  Hypothesis Hconv : conv = 117 \/ conv = 100 \/ conv = 120.
  Hypothesis Fflags : fld SEGS M (sp + 368) 4 0.
  Hypothesis Fwend : fld SEGS M (sp + 368 + 32) 8 (sp + 96).
  Hypothesis Fwpos : fld SEGS M (sp + 368 + 40) 8 (sp + 16).
  Hypothesis Flbf : fld SEGS M (sp + 368 + 144) 4 (2 ^ 32 - 1).
  Hypothesis ROC : ro_clear Ly.L M.
  Hypothesis RRC : relro_clear M.
  Hypothesis FCAN : fld SEGS M A_CANARY 8 rr_canary.

  Let pcs := sp - 544.
  #[local] Abbreviation pcframe := (PcPass2A.pcframe R sp ret).
  #[local] Abbreviation ffile := (PcPass2A.ffile sp).
  #[local] Abbreviation stB := (PcPass2A.stB R M sp ret).

  Record stC (R3 : bvmap 5 word) (M3 : mem) (m nd pl : Z) : Prop := STC {
    c_st : stores_in (fun a => zwin (pcs - 64) sp a \/ zwin (sp + 368 + 40) (sp + 368 + 48) a \/ zwin sp (sp + 8) a) M M3;
    c_pf : pcframe M3;  c_ff : ffile M3 (sp + 16);
    c_112 : fld SEGS M3 (pcs + 112) 8 m; c_24 : fld SEGS M3 (pcs + 24) 8 pl; c_0 : fld SEGS M3 pcs 8 PREFIX_STR;
    c_r2 : getr R3 2%bv = Z_to_bv 64 pcs; c_r23 : getr R3 23%bv = Z_to_bv 64 (pcs + 176 - nd);
    c_r5 : getr R3 5%bv = Z_to_bv 64 0; c_r9 : getr R3 9%bv = Z_to_bv 64 2147483647; c_r18 : getr R3 18%bv = Z_to_bv 64 2147483647;
    c_r19 : getr R3 19%bv = Z_to_bv 64 0; c_r20 : getr R3 20%bv = Z_to_bv 64 (sp + 368); c_r21 : getr R3 21%bv = Z_to_bv 64 (sp + 851);
    c_r22 : getr R3 22%bv = Z_to_bv 64 0; c_r24 : getr R3 24%bv = Z_to_bv 64 0; c_r25 : getr R3 25%bv = Z_to_bv 64 (2 ^ 64 - 1);
    c_r26 : getr R3 26%bv = Z_to_bv 64 0; c_r27 : getr R3 27%bv = Z_to_bv 64 1;
    c_r3 : getr R3 3%bv = getr R 3%bv; c_r4 : getr R3 4%bv = getr R 4%bv;
    c_nd : 0 <= nd <= 20; c_nd0 : nd = 0 <-> m = 0; c_m : 0 <= m < 2 ^ 64; c_pl : pl = 0 \/ pl = 1; c_nc : pl + nd <= 20 }.

  Definition knB (c : Z) : list kentry :=
      [KWr (SA (EVar 20) (-976)) (ELit 1460); KRange (EVar 20) (2 ^ 32 + 976) (2 ^ 47 - 484); KAlign (EVar 20) 16;
       KRange (EVar 8) 37 37; KRange (EVar 9) 2147483647 2147483647; KRange (EVar 18) 2147483647 2147483647; KRange (EVar 19) 0 0;
       KRange (EVar 22) 0 0; KRange (EVar 26) 0 0;
       KWord (SA (EVar 20) 480) (N.to_nat 1) (ELit 37); KWord (SA (EVar 20) 481) (N.to_nat 1) (ELit 108);
       KWord (SA (EVar 20) 482) (N.to_nat 1) (ELit c); KWord (SA (EVar 20) 483) (N.to_nat 1) (ELit 0);
       KWord (SA (EVar 20) 0) (N.to_nat 4) (ELit 0);
       KWord (SA (EVar 20) (-368)) (N.to_nat 8) (EAlu ALU_ADD (EVar 20) (ELit 352)); KWord (SA (EVar 20) 352) (N.to_nat 8) (EVar 32);
       KWord (SA (EVar 20) (-912 + 72)) (N.to_nat 8) (EAlu ALU_ADD (EVar 20) (ELit (-368)));
       KWord (SA (EVar 20) (-912 + 80)) (N.to_nat 8) (ELit 0x12889); KWord (SA (EVar 20) (-912 + 48)) (N.to_nat 8) (ELit 0xfffffffffffeffff);
       KWord (SA (EVar 20) (-912 + 40)) (N.to_nat 8) (ELit MAGIC10_32); KWord (SA (EVar 20) (-912 + 104)) (N.to_nat 8) (ELit 0xccccccc);
       KImg 0x10000 0xe6000; KImg 0xe6000 0xee000].

  Lemma segB : forall R1 M1, stB R1 M1 -> exists R3 M3 m nd pl,
